// Values here are compiled author literals, never HTTP/caller SQL or metadata authority.
const literal=(value:string)=>"'"+value.replaceAll("'","''")+"'";
const same=(actual:string,expected:string)=>`${actual}.type IS json_extract(${expected}.value,'$[0]') COLLATE BINARY AND ${actual}.name IS json_extract(${expected}.value,'$[1]') COLLATE BINARY AND ${actual}.tbl_name IS json_extract(${expected}.value,'$[2]') COLLATE BINARY AND ${actual}.sql IS json_extract(${expected}.value,'$[3]') COLLATE BINARY`;
