export function accountSchemaAdmissionSql():string{return `SELECT CASE WHEN ${FENCE} THEN 1 ELSE 0 END AS admitted,(SELECT count(*) FROM (SELECT 1 FROM main.sqlite_master LIMIT ${EXPECTED_OBJECTS+1})) AS object_count,'${ACCOUNT_SCHEMA_PROFILE_VERSION}' AS profile_version`;}
